#!/bin/sh
logging_tools_menu(){ while :; do c=$(ui_menu 'Logging configuration' "Init: $INIT_SYSTEM" detect 'Detect logging services' logrotate 'Configure logrotate' rsyslog 'Configure rsyslog' syslogng 'Configure syslog-ng' busybox 'Configure BusyBox syslogd' journal 'View recent logs' retention 'Apply low-storage retention profile' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in detect) run_capture Logging sh -c 'ps aux 2>/dev/null | grep -E "[r]syslog|[s]yslog-ng|[s]yslogd|[j]ournald"; ls -l /var/log 2>/dev/null';; logrotate) pkg_install logrotate; edit_file /etc/logrotate.conf;; rsyslog) pkg_install rsyslog; edit_file /etc/rsyslog.conf;; syslogng) pkg_install syslog-ng; edit_file /etc/syslog-ng/syslog-ng.conf;; busybox) replace_block /etc/conf.d/syslog busybox 'SYSLOGD_OPTS="-t -s 256 -b 2"';; journal) run_capture Logs sh -c 'journalctl -n 200 2>/dev/null || tail -n 200 /var/log/messages 2>/dev/null || tail -n 200 /var/log/syslog 2>/dev/null';; retention) write_file /etc/logrotate.d/ish-aok 644 '/var/log/*.log /var/log/messages /var/log/syslog {\n    rotate 3\n    size 1M\n    compress\n    missingok\n    notifempty\n}';; back) return;; esac; done; }
